import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`google-ad-copy`,heroTitle:`Write winning Google Ads in minutes`,heroSubtitle:`Perplexity Computer studies your landing page, researches the search results, and writes high-converting Google ad copy automatically.`,inputUrlCta:`Write my ads`,inputUrlPlaceholder:`www.yourlandingpage.com`,inputUrlPrefill:`Go to {url} and use it as the landing page for a Google Ads copy project. Research the target keyword themes implied by the offer, analyze the top current ads for those themes, and then create 10 complete responsive search ad concepts. For each concept, provide 15 headlines, 4 descriptions, extension ideas, positioning notes, and the audience or intent segment it should target. Highlight the messaging gaps competitors are missing and explain why each angle should improve click-through and conversion rate.`,heroOverlaySteps:[`Reading your landing page and inferring the highest-intent keyword themes`,`Studying top ads, hooks, CTAs, and extensions in the live auction`,`Writing responsive search ad variations tailored to buyer intent`,`Headlines, descriptions, and extension ideas ready for Google Ads`],generatingSteps:[`Opening {url} to extract the offer, proof points, and conversion intent`,`Designing an agent to research keyword themes and live competitor ad copy`,`Configuring RSA headline and description generation for multiple audience angles`,`Preparing a structured ad pack with messaging notes and extension recommendations`],featureSectionTitle:`From landing page to ad account-ready copy`,featureCardTitles:[`Connects to your paid media stack`,`Ad copy ready to ship`],featureCardDescriptions:[`Computer splits the work into SERP research, competitive analysis, messaging strategy, and copywriting, then uses the best model for each step.`,`Google Ads, Sheets, Notion, and Drive can all plug into the workflow so your copy and planning artifacts stay in sync.`,`Responsive search ad assets, extension ideas, angle notes, and competitor gaps come back organized for immediate launch.`],capabilitySectionTitle:`Your paid search copy team, on autopilot`,capabilitySectionSubtitle:`Paste a landing page URL, then come back to a complete pack of Google ad concepts.`,capabilityCards:[{title:`Offer Analysis`,description:`Computer can break down your landing page into audience, promise, proof, objections, and CTA structure before writing any ads.`},{title:`Auction Research`,description:`Computer can inspect the current search landscape to understand the hooks, claims, and positioning your competitors are already using.`},{title:`RSA Copywriting`,description:`Computer can generate headline and description sets optimized for multiple intents, from problem-aware searchers to high-buying-intent traffic.`},{title:`Connect Your Tools`,description:`Computer can move ad drafts into Sheets, Docs, and planning workflows so reviews and iteration happen in the systems you already use.`},{title:`Remember Winning Angles`,description:`Computer can retain your brand voice, approved claims, and high-performing themes for the next round of ad creation.`},{title:`Refresh on Demand`,description:`Computer can periodically revisit the auction and propose new messaging angles when competitors shift or the offer changes.`}]});export{t as default};
